package kr.releasepilot.controlplane.shared.config;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import java.util.UUID;import java.util.concurrent.atomic.AtomicReference;import static org.assertj.core.api.Assertions.*;
class CorrelationIdFilterTests{@Test void preservesValidCorrelationIdAndMakesItAvailableToWork()throws Exception{var request=new MockHttpServletRequest();var response=new MockHttpServletResponse();String id=UUID.randomUUID().toString();request.addHeader(CorrelationIdFilter.HEADER,id);var seen=new AtomicReference<UUID>();new CorrelationIdFilter().doFilter(request,response,(req,res)->seen.set(CorrelationIdFilter.current()));assertThat(response.getHeader(CorrelationIdFilter.HEADER)).isEqualTo(id);assertThat(seen.get().toString()).isEqualTo(id);}@Test void replacesInvalidCorrelationId()throws Exception{var request=new MockHttpServletRequest();var response=new MockHttpServletResponse();request.addHeader(CorrelationIdFilter.HEADER,"unsafe-value");new CorrelationIdFilter().doFilter(request,response,(req,res)->{});assertThatCode(()->UUID.fromString(response.getHeader(CorrelationIdFilter.HEADER))).doesNotThrowAnyException();}}
